package com.orient.ortts.demo;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;
/** Internal deterministic PCM harness, no microphone/download/backend routing changes. */
public final class AsrQaActivity extends Activity {
 TextView view;static volatile boolean running;volatile boolean cancel;
 volatile boolean measuring;Thread memoryThread;long memoryPeakKiB,memorySamples,memoryMaxGapNs;
 void startMemory(File dir){measuring=true;memoryThread=new Thread(()->{try(BufferedWriter out=new BufferedWriter(new FileWriter(new File(dir,"pss-25ms.csv")))){out.write("monotonic_ns,pss_kib\n");long last=0;while(measuring){long t=now();if(last!=0)memoryMaxGapNs=Math.max(memoryMaxGapNs,t-last);last=t;long pss=Debug.getPss();memoryPeakKiB=Math.max(memoryPeakKiB,pss);memorySamples++;out.write(t+","+pss+"\n");long target=t+25000000;while(measuring&&now()<target)SystemClock.sleep(Math.max(1,(target-now())/1000000));}}catch(Exception e){android.util.Log.e("OrTTS-ASR-QA","memory sample",e);}},"asr-pss-sampler");memoryThread.start();}

 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);view=new TextView(this);setContentView(view);view.setText("OrTTS ASR 内部验收");Intent i=getIntent();if(!BuildConfig.DEBUG||running)return;running=true;new Thread(()->execute(i)).start();}
 long now(){return SystemClock.elapsedRealtimeNanos();}double ms(long n){return (now()-n)/1e6;}
 void save(File p,JSONObject v)throws Exception{File tmp=new File(p.getPath()+".tmp");try(FileWriter f=new FileWriter(tmp)){f.write(v.toString(2));}if(!tmp.renameTo(p))throw new IOException("atomic result rename failed");}
 float[] pcm(String name)throws Exception{if(!name.matches("[a-zA-Z0-9_-]+"))throw new IOException("bad fixture");byte[] b=Files.readAllBytes(new File(getFilesDir(),"asr-fixtures/"+name+".f32").toPath());if(b.length%4!=0)throw new IOException("PCM length");float[] p=new float[b.length/4];ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer().get(p);for(float x:p)if(!Float.isFinite(x))throw new IOException("PCM finite");return p;}
 JSONObject trial(JSONObject f,boolean realtime,File dir,String label)throws Exception{
  SpeechBridge.resetAsr();float[] p=pcm(f.getString("id"));JSONArray events=new JSONArray();TreeMap<Long,String> finals=new TreeMap<>();String[] last={""};SpeechBridge.TextSink sink=(text,endpoint,segment)->{try{events.put(new JSONObject().put("text",text).put("endpoint",endpoint).put("segment",segment));last[0]=text;if(endpoint!=0)finals.put(segment,text);}catch(Exception e){throw new RuntimeException(e);}};
  long start=now();double compute=0;int n=0;while(n<p.length){int end=Math.min(n+3200,p.length);if(realtime){long deadline=start+(long)(end*1e9/16000);while(now()<deadline)SystemClock.sleep(Math.max(1,Math.min(10,(deadline-now())/1000000)));}float[] chunk=Arrays.copyOfRange(p,n,end);long t=now();SpeechBridge.accept(chunk,chunk.length,sink);compute+=ms(t);n=end;}
  long t=now();SpeechBridge.finish(sink);compute+=ms(t);double finish=ms(start);String hypothesis=String.join("",finals.values());if(hypothesis.isEmpty())hypothesis=last[0];JSONObject out=new JSONObject(f.toString()).put("hypothesis",hypothesis).put("events",events).put("native_api_ms",compute).put("rtf",compute/(p.length/16.0)).put("input_realtime_paced",realtime).put("input_wall_ms",finish).put("final_latency_ms",realtime?Math.max(0,finish-p.length/16.0):JSONObject.NULL).put("pacing","recorded human PCM, monotonic clock; not microphone capture");save(new File(dir,label+".json"),out);return out;
 }
 void execute(Intent i){String id=i.getStringExtra("asr_id");if(id==null||!id.matches("[a-zA-Z0-9_-]+")){running=false;return;}File dir=new File(getFilesDir(),"asr-qa/"+id);dir.mkdirs();JSONObject result=new JSONObject();JSONArray trials=new JSONArray();startMemory(dir);try{
  long libraryStart=now();SpeechBridge.load();double libraryMs=ms(libraryStart);long start=now();SpeechBridge.openAsr("zipformer_bilingual",new File(getFilesDir(),"speech-models/asr-lite-zh-en-v1").getPath());double load=ms(start);result.put("load_ms",load+libraryMs).put("shared_libraries_ms",libraryMs).put("model_create_ms",load).put("threads",2).put("family","zipformer_bilingual").put("backend","Sherpa/ORT CPU");save(new File(dir,"loaded.json"),result);
  JSONObject fixtures=new JSONObject(new String(Files.readAllBytes(new File(getFilesDir(),"asr-fixtures/FIXTURES.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));JSONArray fs=fixtures.getJSONArray("trials");String action=i.getStringExtra("asr_action");
  if("cold".equals(action))trials.put(trial(fs.getJSONObject(0),false,dir,"cold_first"));
  else if("cancel".equals(action)){
   JSONObject f=fs.getJSONObject(0);float[] p=pcm(f.getString("id"));SpeechBridge.resetAsr();boolean[] fired={false};String callbackError="";
   try{for(int n=0;n<p.length;n+=3200){float[] c=Arrays.copyOfRange(p,n,Math.min(n+3200,p.length));SpeechBridge.accept(c,c.length,(text,e,s)->{if(!fired[0]){fired[0]=true;SpeechBridge.cancel();}});}SpeechBridge.finish((text,e,s)->{if(!fired[0]){fired[0]=true;SpeechBridge.cancel();}});}catch(Exception e){callbackError=e.toString();}result.put("callback_cancel_observed",fired[0]&&!callbackError.isEmpty()).put("callback_cancel_error",callbackError);
   boolean sticky=false;try{SpeechBridge.accept(new float[320],320,(t,e,s)->{});}catch(Exception e){sticky=true;}result.put("sticky_until_reset",sticky);
   JSONObject recovered=trial(f,false,dir,"recovered");SpeechBridge.close();SpeechBridge.openAsr("zipformer_bilingual",new File(getFilesDir(),"speech-models/asr-lite-zh-en-v1").getPath());JSONObject fresh=trial(f,false,dir,"fresh");result.put("next_request_matches_fresh",recovered.getString("hypothesis").equals(fresh.getString("hypothesis")));
   SpeechBridge.resetAsr();long[] signalled={0};Thread c=new Thread(()->{SystemClock.sleep(3);signalled[0]=now();SpeechBridge.cancel();});c.start();String err="";long ended=0;try{SpeechBridge.accept(p,Math.min(p.length,32000),(t,e,s)->{});SpeechBridge.finish((t,e,s)->{});}catch(Exception e){err=e.toString();ended=now();}c.join();result.put("cross_thread_cancel_error",err).put("cross_thread_cancel_ms",ended>0&&signalled[0]>0?(ended-signalled[0])/1e6:JSONObject.NULL);trials.put(trial(f,false,dir,"after_thread_cancel"));
  }else{
   result.put("warmup",trial(fs.getJSONObject(0),false,dir,"warmup"));
   for(int n=0;n<fs.length();n++)trials.put(trial(fs.getJSONObject(n),false,dir,"quality_"+n));
   long stable=now();int rounds=0;while(ms(stable)<600000&&!cancel){JSONObject f=fs.getJSONObject(rounds%fs.length());trials.put(trial(f,true,dir,"stability_"+rounds));rounds++;JSONObject progress=new JSONObject().put("stability_elapsed_ms",ms(stable)).put("completed_realtime",rounds);save(new File(dir,"progress.json"),progress);}
   result.put("stability_elapsed_ms",ms(stable)).put("stability_completed_realtime",rounds);
  }
  result.put("ok",true);
 }catch(Throwable e){try{result.put("ok",false).put("error",e.toString());}catch(Exception ignored){}}finally{try{measuring=false;memoryThread.join(2000);SpeechBridge.close();result.put("memory_peak_pss_kib",memoryPeakKiB).put("memory_samples",memorySamples).put("memory_sampling_target_ms",25).put("memory_max_observed_gap_ms",memoryMaxGapNs/1e6);result.put("trials",trials);save(new File(dir,"RESULT.json"),result);}catch(Exception ignored){}running=false;runOnUiThread(()->view.setText(result.toString()));}}
 public void onDestroy(){cancel=true;try{SpeechBridge.cancel();}catch(Throwable ignored){}super.onDestroy();}
}
